import{I as c,o as s,c as p,b6 as t,J as l,w as o,j as h,a as i}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"Dùng Jobs to Be Done tìm ra việc người dùng thực sự muốn hoàn thành","description":"Bài viết Jobs to Be Done dành cho người mới. Hiểu người dùng không phải mua chức năng, mà đang \\"thuê\\" sản phẩm của bạn để hoàn thành tiến triển trong kịch bản cụ thể, học cách dùng JTBD phân tích hướng sản phẩm, câu hỏi phỏng vấn và AI prompt.","frontmatter":{"title":"Dùng Jobs to Be Done tìm ra việc người dùng thực sự muốn hoàn thành","description":"Bài viết Jobs to Be Done dành cho người mới. Hiểu người dùng không phải mua chức năng, mà đang \\"thuê\\" sản phẩm của bạn để hoàn thành tiến triển trong kịch bản cụ thể, học cách dùng JTBD phân tích hướng sản phẩm, câu hỏi phỏng vấn và AI prompt."},"headers":[],"relativePath":"vi-vn/stage-1/appendix-jobs-to-be-done/index.md","filePath":"vi-vn/stage-1/appendix-jobs-to-be-done/index.md"}'),u={name:"vi-vn/stage-1/appendix-jobs-to-be-done/index.md"},d=Object.assign(u,{setup(e){const a="Khoảng <strong>1.5 giờ</strong>";return(r,n)=>{const g=c("ChapterIntroduction");return s(),p("div",null,[n[1]||(n[1]=t('<h1 id="dung-jobs-to-be-done-tim-ra-viec-nguoi-dung-thuc-su-muon-hoan-thanh" tabindex="-1">Dùng Jobs to Be Done tìm ra việc người dùng thực sự muốn hoàn thành <a class="header-anchor" href="#dung-jobs-to-be-done-tim-ra-viec-nguoi-dung-thuc-su-muon-hoan-thanh" aria-label="Permalink to “Dùng Jobs to Be Done tìm ra việc người dùng thực sự muốn hoàn thành”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="huong-dan-chuong-nay" tabindex="-1">Hướng dẫn chương này <a class="header-anchor" href="#huong-dan-chuong-nay" aria-label="Permalink to “Hướng dẫn chương này”">​</a></h2>',3)),l(g,{duration:a,tags:["JTBD","Nhu cầu người dùng","Tư duy sản phẩm","Insight nhu cầu"],coreOutput:"1 câu JTBD giống nhu cầu thực tế hơn",expectedOutput:"Có thể thu ý tưởng mơ hồ thành kịch bản người dùng và hướng MVP cụ thể hơn"},{default:o(()=>[...n[0]||(n[0]=[h("p",null,'Rất nhiều người vừa bắt đầu làm sản phẩm, sai lầm dễ phạm phải nhất là đặt toàn bộ sự chú ý lên "tôi muốn làm chức năng gì". Thấy người khác có phân loại thông minh, bạn cũng muốn thêm; thấy người khác có tóm tắt tự động, bạn cũng muốn kết nối; thấy người khác làm Agent, đa mô thức, workflow, bạn cũng cảm thấy không thể thiếu.',-1),h("p",null,'Nhưng trong thực tế, người dùng hiếm khi vì "tên chức năng này rất ngầu" mới quyết định dùng một sản phẩm. Họ nhiều hơn là ở một thời điểm cụ thể, muốn đẩy một việc tiến lên phía trước, thế là tạm thời "thuê" một công cụ, một dịch vụ, thậm chí một người, để giúp mình hoàn thành bước này.',-1),h("p",null,[i("Đây chính là điều phương pháp "),h("strong",null,"Jobs to Be Done (JTBD)"),i(" muốn nhắc chúng ta: "),h("strong",null,"Người dùng không phải đang mua bản thân chức năng, mà đang thuê một loại giải pháp nào đó, giúp mình hoàn thành một tiến triển.")],-1),h("p",null,"Bài viết này sẽ dùng ngôn ngữ dễ hiểu nhất, đưa bạn từ không hiểu gì đến hiểu JTBD, và biến nó thành công cụ phân tích bạn có thể trực tiếp dùng khi làm ứng dụng AI.",-1)])]),_:1}),n[2]||(n[2]=t(`<div class="info custom-block"><p class="custom-block-title">SOP tối thiểu</p><p><strong>Mục đích</strong>: Sau khi đọc xong, bạn sẽ rõ hơn cách thu một ý tưởng mơ hồ thành một câu nhu cầu thực sự có kịch bản người dùng, thay vì trong đầu chỉ có một đống tên chức năng.</p><p><strong>Hành động</strong>: Viết 1 câu ý tưởng mơ hồ, tìm 3 người dùng tiềm năng trò chuyện &quot;lần gần nhất xử lý thế nào&quot;, rồi sắp xếp thành 1 câu JTBD.</p><p><strong>Kết quả</strong>: Bạn sẽ có một giả định nhu cầu rõ ràng hơn, biết phiên bản đầu nên giải quyết gì trước.</p><p><strong>Từ khóa chuyển nhanh</strong>: <a href="#jtbd-what">JTBD là gì</a> · <a href="#jtbd-formula">Công thức một câu</a> · <a href="#jtbd-ai">AI giúp bạn thế nào</a></p></div><h2 id="ban-se-hoc-đuoc-nhung-noi-dung-sau" tabindex="-1">Bạn sẽ học được những nội dung sau <a class="header-anchor" href="#ban-se-hoc-đuoc-nhung-noi-dung-sau" aria-label="Permalink to “Bạn sẽ học được những nội dung sau”">​</a></h2><ol><li>Jobs to Be Done là gì, tại sao nó gần với nhu cầu thực tế hơn &quot;brainstorm chức năng&quot;</li><li>Cách phân biệt &quot;chức năng người dùng nói muốn&quot; và &quot;việc người dùng thực sự muốn hoàn thành&quot;</li><li>Dùng một template đơn giản thế nào, để thu một ý tưởng mơ hồ thành kịch bản, kích hoạt, rào cản và tiêu chuẩn thành công</li><li>Cách dùng JTBD trong sản phẩm AI, câu hỏi phỏng vấn và sắp xếp AI prompt</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-jobs-to-be-done-la-gi" tabindex="-1"><a href="#top-jtbd">1. Jobs to Be Done là gì</a> <a class="header-anchor" href="#_1-jobs-to-be-done-la-gi" aria-label="Permalink to “1. Jobs to Be Done là gì”">​</a></h2><p>Jobs to Be Done thường được viết tắt là <strong>JTBD</strong>. Ý tưởng cốt lõi phía sau nó, liên quan đến cách diễn đạt kinh điển mà nhóm Clayton Christensen phổ biến: <strong>Người dùng sẽ &quot;thuê&quot; một sản phẩm nào đó để hoàn thành một việc.</strong></p><p>&quot;Việc&quot; ở đây, không phải loại hành động bề mặt trong to-do list, mà là một <strong>tiến triển</strong> mà người dùng hy vọng trạng thái của mình sẽ xảy ra. Ví dụ:</p><ul><li>Không phải &quot;tôi muốn một công cụ biên bản AI&quot;, mà là &quot;tôi muốn trong vòng 10 phút sau cuộc họp sắp xếp rõ trọng tâm, việc cần làm và người phụ trách, đừng nữa dựa vào trí nhớ bù ghi chú&quot;</li><li>Không phải &quot;tôi muốn một App ghi chép&quot;, mà là &quot;tôi muốn biết tiền rốt cuộc tiêu đi đâu, để cuối tháng đừng nữa lo lắng&quot;</li><li>Không phải &quot;tôi muốn một công cụ tối ưu CV&quot;, mà là &quot;tôi muốn nộp một CV khá đàng hoàng với nhiều tự tin hơn, không muốn mỗi lần nộp đều hoài nghi mình viết quá kém&quot;</li></ul><p>Vì vậy, <strong>JTBD quan tâm không phải sản phẩm trông thế nào, mà là tại sao người dùng cần nó vào thời điểm này.</strong></p><p>Đây cũng là lý do rất nhiều sản phẩm nhìn có vẻ khác nhau, thực tế đang cạnh tranh cùng một job. Người dùng muốn &quot;trên đường đi làm không nhàm chán&quot;, đối tượng có thể thuê bao gồm video ngắn, podcast, game, chat, thậm chí ngủ gật. Người dùng muốn &quot;nhanh chóng hiểu một PDF rất dài&quot;, đối tượng có thể thuê bao gồm công cụ tóm tắt AI, thực tập sinh, đồng nghiệp, tự mình cố đọc, hoặc đơn giản là không xem trước.</p><p>Một khi bạn dùng góc nhìn này để xem vấn đề, bạn sẽ phát hiện đối thủ cạnh tranh thực sự của bạn, thường không chỉ là &quot;một App khác trông giống bạn&quot;, mà là <strong>tất cả giải pháp thay thế mà người dùng hiện tại có thể chấp nhận</strong>.</p><h2 id="_2-jtbd-khac-gi-voi-chan-dung-nguoi-dung-va-danh-sach-chuc-nang" tabindex="-1">2. JTBD khác gì với chân dung người dùng và danh sách chức năng <a class="header-anchor" href="#_2-jtbd-khac-gi-voi-chan-dung-nguoi-dung-va-danh-sach-chuc-nang" aria-label="Permalink to “2. JTBD khác gì với chân dung người dùng và danh sách chức năng”">​</a></h2><p>Rất nhiều người mới vừa bắt đầu phân tích nhu cầu, sẽ trước viết chân dung người dùng: 25 tuổi, nữ, thành phố tuyến 1, dân văn phòng, thích công cụ hiệu quả, sẵn sàng thử sản phẩm mới. Loại thông tin này không thể nói hoàn toàn vô dụng, nhưng nó thường <strong>không đủ giải thích tại sao một người sẽ hành động vào thời điểm này.</strong></p><p>JTBD quan tâm hơn đến những vấn đề dưới đây:</p><ul><li>Anh/chị trong kịch bản nào quyết định tìm giải pháp</li><li>Lúc đó rốt cuộc bị kẹt cái gì</li><li>Anh/chị muốn đẩy việc gì bước tới bước tiếp theo</li><li>Hiện đang dùng cách vụng về nào gồng gánh</li><li>Nếu việc giải quyết tốt, kết quả nào sẽ khiến anh/chị thấy &quot;đáng&quot;</li></ul><p>Nói cách khác, <strong>chân dung người dùng giống hơn &quot;người này đại khái là ai&quot;, JTBD giống hơn &quot;người này hiện tại rốt cuộc muốn hoàn thành cái gì&quot;.</strong></p><p>Tương tự, danh sách chức năng cũng dễ dẫn dắt sai hướng. Người dùng nói &quot;tôi muốn xuất Word&quot;, &quot;tôi muốn AI sửa viết&quot;, &quot;tôi muốn nhập giọng nói&quot;, đây đều chỉ là diễn đạt bề mặt. JTBD sẽ tiếp tục hỏi sâu:</p><ul><li>Tại sao bạn hiện tại cần xuất Word, chứ không phải PDF?</li><li>Bạn muốn sửa viết, là vì văn phong quá kém, hay vì cần phù hợp với đối tượng khác nhau?</li><li>Bạn muốn nhập giọng nói, là vì lười gõ phím, hay vì bạn thường xuyên đang đi bộ, đang lái xe, vừa họp xong cần ghi chép ngay?</li></ul><p>Rất nhiều lúc, <strong>chức năng chỉ là một loại dịch thuật tạm thời của job</strong>. Nếu bạn chỉ thu thập chức năng, rất dễ làm sản phẩm thành &quot;người dùng nói gì thì chất gì&quot;; Nếu bạn nhìn thấy job phía sau, mới có nhiều cơ hội làm ra giải pháp thực sự thuận tay, thực sự có sức cạnh tranh.</p><h2 id="_3-mot-vi-du-nguoi-moi-cung-co-the-hieu" tabindex="-1">3. Một ví dụ người mới cũng có thể hiểu <a class="header-anchor" href="#_3-mot-vi-du-nguoi-moi-cung-co-the-hieu" aria-label="Permalink to “3. Một ví dụ người mới cũng có thể hiểu”">​</a></h2><p>Trước đừng vội nghĩ đến sản phẩm AI phức tạp, chúng ta bắt đầu từ một ví dụ cuộc sống.</p><p>Giả sử có người trước khi ra cửa buổi sáng luôn không kịp ăn sáng, nên thường xuyên mua sandwich và cà phê ở cửa tàu điện ngầm. Nhìn bề ngoài, anh ấy &quot;mua&quot; là bữa sáng; nhưng nếu nhìn bằng JTBD, việc anh ấy thực sự muốn hoàn thành có thể là:</p><ul><li>Trong buổi sáng vội vã, dùng cách ít tốn sức não nhất giải quyết một bữa ăn</li><li>Để mình trước khi đến công ty không bị đói phát hoảng</li><li>Không vì ăn sáng mà ảnh hưởng nhịp độ đi làm</li></ul><p>Lúc này, người dùng thuê không phải &quot;sandwich của một thương hiệu cố định nào đó&quot;, mà là một giải pháp giúp anh ấy đẩy buổi sáng thuận lợi tiến lên. Nếu cửa hàng tiện lợi bên cạnh nhanh hơn, gần hơn, ổn định hơn, anh ấy có thể ngay lập tức đổi lựa chọn ban đầu.</p><p>Đem logic này sang sản phẩm AI thì rõ ràng hơn.</p><p>Ví dụ bạn muốn làm một &quot;công cụ biên bản cuộc họp AI&quot;. Nếu chỉ dừng lại ở cấp chức năng, bạn sẽ rất dễ bắt đầu nghĩ:</p><ul><li>Có nên hỗ trợ upload audio không</li><li>Có nên kết nối tách người nói không</li><li>Có nên xuất Markdown không</li><li>Có nên tự động sinh việc cần làm không</li></ul><p>Những điều này đều không sai, nhưng chưa đủ. Dùng JTBD hỏi thêm một tầng, việc người dùng thực sự muốn hoàn thành có thể là:</p><ul><li>Tôi muốn trong 10 phút sau cuộc họp, đồng bộ kết quả thảo luận cho người không tham dự</li><li>Tôi muốn trích xuất sạch việc cần làm, người phụ trách và thời hạn, đừng để nhóm dựa vào trí nhớ phối hợp</li><li>Tôi muốn giảm thời gian sắp xếp nội dung cuộc họp lặp đi lặp lại, dành sức lực cho quyết sách và thúc đẩy</li></ul><p>Một khi job được nói rõ, rất nhiều ưu tiên chức năng sẽ tự động nổi lên. Phiên bản đầu quan trọng nhất có thể không phải &quot;hỗ trợ 12 định dạng xuất&quot;, mà là:</p><ul><li>Cấu trúc biên bản đủ rõ ràng</li><li>Trích xuất việc cần làm ổn định</li><li>Link chia sẻ thuận tiện</li><li>Kết quả xuất ra khiến người ta dám trực tiếp chuyển tiếp cho nhóm</li></ul><p>Đây là giá trị của JTBD: <strong>Nó có thể giúp bạn từ &quot;tôi muốn chất những khả năng nào&quot; quay về &quot;tôi muốn giúp người dùng thúc đẩy tiến triển gì&quot;.</strong></p><h2 id="_4-mot-template-jtbd-huu-dung" tabindex="-1">4. Một template JTBD hữu dụng <a class="header-anchor" href="#_4-mot-template-jtbd-huu-dung" aria-label="Permalink to “4. Một template JTBD hữu dụng”">​</a></h2><p>Nếu bạn là người mới, có thể trước đừng cố nghĩ JTBD quá học thuật. Trước nắm 5 yếu tố thực dụng nhất là đủ.</p><h3 id="_4-1-kich-ban" tabindex="-1">4.1 Kịch bản <a class="header-anchor" href="#_4-1-kich-ban" aria-label="Permalink to “4.1 Kịch bản”">​</a></h3><p>Người dùng ở thời điểm nào, trong môi trường nào nhớ đến sản phẩm này?</p><ul><li>Là sau khi họp xong</li><li>Là lúc sếp đột xuất đòi tài liệu</li><li>Là buổi tối chuẩn bị nộp CV</li><li>Là cuối tháng phát hiện tiền lại không đủ</li></ul><p><strong>Nhu cầu không có kịch bản, thường đều chưa đủ thực tế.</strong></p><h3 id="_4-2-kich-hoat" tabindex="-1">4.2 Kích hoạt <a class="header-anchor" href="#_4-2-kich-hoat" aria-label="Permalink to “4.2 Kích hoạt”">​</a></h3><p>Là cái gì khiến anh/chị quyết định ngay lập tức tìm giải pháp?</p><ul><li>Bị đè nén bởi tài liệu dài, không biết bắt đầu đọc từ đâu</li><li>Ngày mai phải nộp tài liệu, hôm nay mới phát hiện format lộn xộn</li><li>Vừa bị sếp hỏi tiến độ, nhận ra mình chưa sắp xếp rõ ràng</li><li>Muốn kiên trì ghi chép, nhưng viết tay, copy, sắp xếp đều quá phiền</li></ul><p>Điểm kích hoạt thường mang theo cảm xúc. Cảm xúc này rất quan trọng, vì nó quyết định tại sao người dùng sẽ hành động vào khoảnh khắc này.</p><h3 id="_4-3-tien-trien-muon-hoan-thanh" tabindex="-1">4.3 Tiến triển muốn hoàn thành <a class="header-anchor" href="#_4-3-tien-trien-muon-hoan-thanh" aria-label="Permalink to “4.3 Tiến triển muốn hoàn thành”">​</a></h3><p>Anh/chị không chỉ muốn &quot;làm một hành động&quot;, mà muốn đẩy mình tiến tới trạng thái mới nào?</p><ul><li>Từ hỗn loạn đến rõ ràng</li><li>Từ lo lắng đến an tâm</li><li>Từ trì hoãn đến khởi động</li><li>Từ kém hiệu quả đến thuận tay</li><li>Từ nói không rõ ràng đến có thể trực tiếp giao nộp</li></ul><p>Trong bước này, từ &quot;tiến triển&quot; rất then chốt. Vì rất nhiều người thực sự mua không phải công cụ, mà là <strong>sự thay đổi trạng thái</strong>.</p><h3 id="_4-4-giai-phap-thay-the-hien-tai" tabindex="-1">4.4 Giải pháp thay thế hiện tại <a class="header-anchor" href="#_4-4-giai-phap-thay-the-hien-tai" aria-label="Permalink to “4.4 Giải pháp thay thế hiện tại”">​</a></h3><p>Hiện không có sản phẩm của bạn, anh/chị làm thế nào?</p><ul><li>Thủ công copy paste</li><li>Dùng Excel hoặc sổ tay gồng gánh</li><li>Tìm đồng nghiệp giúp đỡ</li><li>Kéo dài không làm</li><li>Chuyển qua lại giữa vài công cụ</li></ul><p>Ai là giải pháp thay thế, ai là môi trường cạnh tranh thực sự của bạn.</p><h3 id="_4-5-tieu-chuan-thanh-cong" tabindex="-1">4.5 Tiêu chuẩn thành công <a class="header-anchor" href="#_4-5-tieu-chuan-thanh-cong" aria-label="Permalink to “4.5 Tiêu chuẩn thành công”">​</a></h3><p>Việc thế nào mới tính thực sự được giải quyết?</p><ul><li>Trong 10 phút nhận được kết quả có thể chia sẻ</li><li>Không cần sửa lớn lần hai đã có thể gửi cho người khác</li><li>Không dễ bị sót, bị sai, quên việc</li><li>Lần đầu dùng đã biết bước tiếp theo làm gì</li></ul><p>Nếu bạn thậm chí &quot;người dùng đánh giá đáng hay không&quot; đều nói không rõ, thì hướng này đa số chưa được thu tốt.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-cong-thuc-mot-cau-co-the-ap-dung-truc-tiep" tabindex="-1"><a href="#top-jtbd">5. Công thức một câu có thể áp dụng trực tiếp</a> <a class="header-anchor" href="#_5-cong-thuc-mot-cau-co-the-ap-dung-truc-tiep" aria-label="Permalink to “5. Công thức một câu có thể áp dụng trực tiếp”">​</a></h2><p>Khi bạn muốn sắp xếp một hướng sản phẩm, có thể trước áp câu rất thực dụng này:</p><blockquote><p>Khi __________, tôi muốn __________, để __________. Hiện tôi chỉ có thể thông qua __________ để miễn cưỡng hoàn thành việc này.</p></blockquote><p>Ví dụ:</p><blockquote><p>Khi tôi vừa xong một cuộc họp dự án với lượng thông tin rất lớn, tôi muốn nhanh chóng nhận được một biên bản kèm việc cần làm, người phụ trách và thời hạn, để tôi có thể ngay lập tức đồng bộ nhóm và thúc đẩy thực hiện. Hiện tôi chỉ có thể dựa vào tự mình nhớ, lướt lịch sử chat và thủ công sắp xếp để miễn cưỡng hoàn thành việc này.</p></blockquote><p>Lại ví dụ:</p><blockquote><p>Khi tôi chuẩn bị nộp một vị trí mới, tôi muốn nhanh chóng sửa kinh nghiệm hiện có thành phiên bản phù hợp với vị trí hơn, để tôi có thể nộp một CV khá đàng hoàng với nhiều tự tin hơn. Hiện tôi chỉ có thể liên tục copy CV cũ, sửa cách diễn đạt bằng tay, sửa đến cuối cùng càng ngày càng không chắc chắn.</p></blockquote><p>Nếu bạn có thể viết một câu rõ ràng đến mức này, thiết kế trang, thiết kế prompt, đánh giá ưu tiên chức năng phía sau, đều sẽ dễ hơn nhiều.</p><h2 id="_6-khi-lam-san-pham-ai-đac-biet-phai-xem-ba-tang-job" tabindex="-1">6. Khi làm sản phẩm AI, đặc biệt phải xem ba tầng job <a class="header-anchor" href="#_6-khi-lam-san-pham-ai-đac-biet-phai-xem-ba-tang-job" aria-label="Permalink to “6. Khi làm sản phẩm AI, đặc biệt phải xem ba tầng job”">​</a></h2><p>Rất nhiều sản phẩm AI khi demo chức năng trông rất mạnh, nhưng sau khi thực sự lên mạng lại không giữ chân được người dùng, lý do phổ biến là chỉ giải quyết hành động bề mặt, chưa giải quyết job sâu hơn.</p><p>Bạn có thể thô chia một job thành ba tầng để xem:</p><h3 id="_6-1-tang-chuc-nang" tabindex="-1">6.1 Tầng chức năng <a class="header-anchor" href="#_6-1-tang-chuc-nang" aria-label="Permalink to “6.1 Tầng chức năng”">​</a></h3><p>Nhiệm vụ bề mặt nhất là gì?</p><ul><li>Tóm tắt tài liệu</li><li>Sửa viết văn bản</li><li>Trích xuất việc cần làm</li><li>Tạo hình ảnh</li></ul><p>Đây là tầng dễ nói ra nhất bằng miệng người dùng.</p><h3 id="_6-2-tang-cam-xuc" tabindex="-1">6.2 Tầng cảm xúc <a class="header-anchor" href="#_6-2-tang-cam-xuc" aria-label="Permalink to “6.2 Tầng cảm xúc”">​</a></h3><p>Người dùng hy vọng giảm bớt sự không thoải mái nào, hoặc thu được cảm giác gì?</p><ul><li>Không muốn hoảng hốt như vậy</li><li>Không muốn trông thiếu chuyên nghiệp</li><li>Không muốn mỗi lần đều bắt đầu từ đầu</li><li>Muốn có nhiều cảm giác kiểm soát hơn</li></ul><p>Rất nhiều ý muốn trả phí, thực tế quan hệ rất lớn với tầng cảm xúc.</p><h3 id="_6-3-tang-xa-hoi" tabindex="-1">6.3 Tầng xã hội <a class="header-anchor" href="#_6-3-tang-xa-hoi" aria-label="Permalink to “6.3 Tầng xã hội”">​</a></h3><p>Người dùng hy vọng trong mắt người khác trở thành kiểu người nào?</p><ul><li>Trông đáng tin cậy hơn</li><li>Có khả năng tổ chức hơn trong nhóm</li><li>Chuyên nghiệp hơn trước mặt khách hàng</li><li>Biết diễn đạt hơn trên nền tảng xã hội</li></ul><p>Nếu bạn chỉ làm tầng chức năng, sản phẩm rất dễ bị thay thế; Nếu bạn đồng thời hiểu tầng cảm xúc và tầng xã hội, bạn sẽ dễ tìm được giá trị có độ dính thực sự hơn.</p><h2 id="_7-dung-jtbd-nguoc-lai-sang-loc-huong-san-pham" tabindex="-1">7. Dùng JTBD ngược lại sàng lọc hướng sản phẩm <a class="header-anchor" href="#_7-dung-jtbd-nguoc-lai-sang-loc-huong-san-pham" aria-label="Permalink to “7. Dùng JTBD ngược lại sàng lọc hướng sản phẩm”">​</a></h2><p>Đôi khi không phải bạn đã có sản phẩm, mà trong tay có 3 đến 5 ý tưởng, không biết làm cái nào. Lúc này JTBD rất phù hợp để làm sàng lọc.</p><p>Bạn có thể cầm mỗi ý tưởng, lần lượt hỏi mình 5 câu:</p><ol><li>Kịch bản tương ứng với ý tưởng này có đủ cụ thể không?</li><li>Người dùng hiện đã dùng cách vụng về nào đó để giải quyết chưa?</li><li>Mức độ đau của job này có đủ mạnh, hoặc tần suất có đủ cao không?</li><li>Nếu tôi làm tốt, người dùng có cảm nhận rõ ràng &quot;trạng thái tốt lên&quot; không?</li><li>Phiên bản đầu có thể chỉ xoay quanh bước quan trọng nhất của job này, làm ra một phiên bản rất nhỏ nhưng hữu dụng không?</li></ol><p>Nếu một hướng nói đến cuối cùng vẫn chỉ có thể nói &quot;cảm giác khá thú vị&quot;, nhưng nói không rõ kích hoạt, giải pháp thay thế và tiêu chuẩn thành công, thì nó đa số vẫn chỉ là một cảm hứng mơ hồ, không phải một hướng trưởng thành.</p><h2 id="_8-cau-hoi-co-the-truc-tiep-mang-đi-phong-van-nguoi-dung" tabindex="-1">8. Câu hỏi có thể trực tiếp mang đi phỏng vấn người dùng <a class="header-anchor" href="#_8-cau-hoi-co-the-truc-tiep-mang-đi-phong-van-nguoi-dung" aria-label="Permalink to “8. Câu hỏi có thể trực tiếp mang đi phỏng vấn người dùng”">​</a></h2><p>Rất nhiều người vừa làm nghiên cứu đã hỏi: &quot;Bạn muốn chức năng gì?&quot; Cách hỏi này rất dễ nhận được câu trả lời bề mặt.</p><p>JTBD phù hợp hỏi những câu dưới đây:</p><ul><li>Lần gần nhất bạn gặp vấn đề này là khi nào?</li><li>Lúc đó bạn đang làm gì, tại sao bị kẹt?</li><li>Cuối cùng bạn đã giải quyết thế nào?</li><li>Trong quá trình này, nơi phiền nhất, chậm nhất, không yên tâm nhất là gì?</li><li>Nếu có một công cụ giúp bạn, kết quả nào khiến bạn thấy thực sự hữu dụng?</li><li>Bạn đã thử cách thay thế nào? Tại sao chúng không đủ tốt?</li></ul><p>Lợi ích của cách hỏi này: Nó sẽ kéo đối thoại về trải nghiệm thực tế, thay vì dừng lại ở sở thích trong tưởng tượng.</p><h2 id="_9-dung-ai-giup-ban-phan-tich-jtbd" tabindex="-1">9. Dùng AI giúp bạn phân tích JTBD <a class="header-anchor" href="#_9-dung-ai-giup-ban-phan-tich-jtbd" aria-label="Permalink to “9. Dùng AI giúp bạn phân tích JTBD”">​</a></h2><p>Bản thân JTBD không phải do AI phát minh, nhưng AI rất phù hợp giúp bạn sắp xếp và tinh lọc JTBD.</p><p>Ví dụ bạn đã thu thập 5 đến 10 phản hồi người dùng, có thể ném cho mô hình, để nó tổng kết theo cấu trúc dưới đây:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Xin đóng vai trợ lý nghiên cứu sản phẩm.</span></span>
<span class="line"><span>Tôi sẽ cho bạn một số lời gốc của người dùng, xin đừng cho gợi ý chức năng trước,</span></span>
<span class="line"><span>mà trước sắp xếp theo framework Jobs to Be Done:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Người dùng đang ở kịch bản nào</span></span>
<span class="line"><span>2. Sự kiện kích hoạt anh/chị hành động là gì</span></span>
<span class="line"><span>3. Tiến triển anh/chị thực sự muốn hoàn thành là gì</span></span>
<span class="line"><span>4. Giải pháp thay thế hiện tại là gì</span></span>
<span class="line"><span>5. Tiêu chuẩn thành công anh/chị quan tâm nhất là gì</span></span>
<span class="line"><span>6. Những từ cảm xúc xuất hiện lặp đi lặp lại trong những phản hồi này là gì</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cuối cùng, xin sắp xếp nội dung này thành 3 giả định JTBD đáng ưu tiên xác minh nhất.</span></span></code></pre></div><p>Nếu bạn đã có một ý tưởng, cũng có thể để AI giúp bạn làm vòng thu thứ nhất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi muốn làm một [ý tưởng sản phẩm của bạn].</span></span>
<span class="line"><span>Xin đừng trực tiếp cho tôi danh sách chức năng, mà dùng phương pháp Jobs to Be Done giúp tôi phân tích:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Sản phẩm này có thể phục vụ những kịch bản cụ thể nào</span></span>
<span class="line"><span>2. Job cốt lõi người dùng muốn hoàn thành trong mỗi kịch bản là gì</span></span>
<span class="line"><span>3. Những giải pháp thay thế hiện có nào</span></span>
<span class="line"><span>4. Job nào phù hợp nhất làm điểm khởi đầu MVP, tại sao</span></span>
<span class="line"><span>5. Xin viết job cuối cùng được đề xuất thành một câu JTBD rõ ràng</span></span></code></pre></div><p>Lợi ích của việc này là, bạn sẽ không vừa lên đã bị AI dẫn đi &quot;brainstorm 50 chức năng&quot;, mà trước làm rõ hướng đã.</p><h2 id="_10-4-sai-lam-pho-bien-nhat-cua-nguoi-moi" tabindex="-1">10. 4 sai lầm phổ biến nhất của người mới <a class="header-anchor" href="#_10-4-sai-lam-pho-bien-nhat-cua-nguoi-moi" aria-label="Permalink to “10. 4 sai lầm phổ biến nhất của người mới”">​</a></h2><h3 id="_10-1-viet-job-thanh-ten-chuc-nang" tabindex="-1">10.1 Viết job thành tên chức năng <a class="header-anchor" href="#_10-1-viet-job-thanh-ten-chuc-nang" aria-label="Permalink to “10.1 Viết job thành tên chức năng”">​</a></h3><p>&quot;AI tóm tắt&quot;, &quot;phân loại thông minh&quot;, &quot;tự động tạo&quot; đều không phải job, chúng chỉ là cách triển khai khả thi.</p><h3 id="_10-2-viet-nhom-nguoi-rat-rong" tabindex="-1">10.2 Viết nhóm người rất rộng <a class="header-anchor" href="#_10-2-viet-nhom-nguoi-rat-rong" aria-label="Permalink to “10.2 Viết nhóm người rất rộng”">​</a></h3><p>&quot;Tất cả dân văn phòng&quot;, &quot;tất cả sinh viên&quot;, &quot;tất cả doanh nhân&quot; thường đều quá rộng. Càng rộng, bạn càng khó nhìn thấy kịch bản thực tế.</p><h3 id="_10-3-chi-nghe-nguoi-dung-noi-khong-xem-nguoi-dung-lam-the-nao" tabindex="-1">10.3 Chỉ nghe người dùng nói, không xem người dùng làm thế nào <a class="header-anchor" href="#_10-3-chi-nghe-nguoi-dung-noi-khong-xem-nguoi-dung-lam-the-nao" aria-label="Permalink to “10.3 Chỉ nghe người dùng nói, không xem người dùng làm thế nào”">​</a></h3><p>Người dùng sẽ mô tả mình muốn gì, nhưng ưu tiên thực sự của họ, thường giấu trong cách họ hiện khắc phục tạm thời giải quyết vấn đề.</p><h3 id="_10-4-vua-bat-đau-đa-muon-lam-nen-tang-hoan-chinh" tabindex="-1">10.4 Vừa bắt đầu đã muốn làm nền tảng hoàn chỉnh <a class="header-anchor" href="#_10-4-vua-bat-đau-đa-muon-lam-nen-tang-hoan-chinh" aria-label="Permalink to “10.4 Vừa bắt đầu đã muốn làm nền tảng hoàn chỉnh”">​</a></h3><p>Cách mở đúng của JTBD, thường không phải &quot;tôi làm một nền tảng vạn năng bao trùm&quot;, mà là trước tiên tập trung vào một bước quan trọng nhất trong một kịch bản, làm nó rất thuận tay.</p><h2 id="_11-tom-tat" tabindex="-1">11. Tóm tắt <a class="header-anchor" href="#_11-tom-tat" aria-label="Permalink to “11. Tóm tắt”">​</a></h2><p>Giá trị lớn nhất của Jobs to Be Done, không phải cho bạn một danh từ mới, mà giúp bạn đổi một góc quan sát: <strong>Đừng chỉ tập trung vào chức năng sản phẩm, mà hãy tập trung vào việc người dùng muốn đẩy cái gì bước tới bước tiếp theo.</strong></p><p>Khi bạn bắt đầu liên tục hỏi mình:</p><ul><li>Người dùng trong kịch bản nào thuê sản phẩm này</li><li>Anh/chị rốt cuộc bị kẹt ở đâu</li><li>Hiện đang dùng cách nào gồng gánh</li><li>Sau khi việc giải quyết xong, trạng thái sẽ thay đổi thế nào</li></ul><p>Bạn sẽ phát hiện, rất nhiều ý tưởng mơ hồ ban đầu bỗng trở nên rõ ràng, rất nhiều chức năng hoa mỹ cũng bỗng không quan trọng như vậy.</p><p>Làm sản phẩm, đặc biệt là làm sản phẩm AI, sợ nhất là vừa bắt đầu đã đắm chìm trong trưng bày khả năng. JTBD có thể giúp kéo sự chú ý của bạn về nơi thực sự quan trọng: <strong>Tại sao người dùng cần bạn, và bạn rốt cuộc đang giúp anh/chị hoàn thành tiến triển gì.</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-cach-dung-ai-giup-ban-thuc-hanh-jtbd" tabindex="-1"><a href="#top-jtbd">12. Cách dùng AI giúp bạn thực hành JTBD</a> <a class="header-anchor" href="#_12-cach-dung-ai-giup-ban-thuc-hanh-jtbd" aria-label="Permalink to “12. Cách dùng AI giúp bạn thực hành JTBD”">​</a></h2><p>JTBD không phải do AI phát minh, nhưng AI rất phù hợp đóng vai trợ lý nghiên cứu, trợ lý sắp xếp và trợ lý đối chiếu trong phương pháp này. Điểm mấu chốt là: <strong>Để AI giúp bạn sắp xếp và mở rộng, thay vì thay bạn phỏng đoán người dùng.</strong></p><p>Bạn có thể dùng như sau:</p><h3 id="_12-1-đe-ai-giup-ban-viet-lai-y-tuong-mo-ho-thanh-gia-đinh-jtbd" tabindex="-1">12.1 Để AI giúp bạn viết lại ý tưởng mơ hồ thành giả định JTBD <a class="header-anchor" href="#_12-1-đe-ai-giup-ban-viet-lai-y-tuong-mo-ho-thanh-gia-đinh-jtbd" aria-label="Permalink to “12.1 Để AI giúp bạn viết lại ý tưởng mơ hồ thành giả định JTBD”">​</a></h3><p>Khi trong đầu bạn chỉ có một câu mô tả mơ hồ, ví dụ &quot;tôi muốn làm một công cụ giúp sinh viên tìm thực tập&quot;, có thể trước để AI giúp bạn tách thành vài job khả dĩ:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi hiện có một ý tưởng sản phẩm mơ hồ: [Ý tưởng của bạn]</span></span>
<span class="line"><span>Xin đừng trực tiếp cho tôi danh sách chức năng, mà dùng cách Jobs to Be Done giúp tôi phân tích:</span></span>
<span class="line"><span>1. Có thể tương ứng với những kịch bản cụ thể nào</span></span>
<span class="line"><span>2. Trong mỗi kịch bản, tiến triển người dùng thực sự muốn hoàn thành là gì</span></span>
<span class="line"><span>3. Giải pháp thay thế hiện tại có thể là gì</span></span>
<span class="line"><span>4. Job nào phù hợp nhất làm MVP trước</span></span>
<span class="line"><span>Xin cuối cùng viết mỗi job thành một câu JTBD rõ ràng.</span></span></code></pre></div><p>Bạn thậm chí có thể viết input rất nhỏ:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi muốn làm một thứ giúp sinh viên tìm thực tập.</span></span>
<span class="line"><span>Tôi hiện cũng nói không rõ cụ thể làm cái gì, bạn giúp tôi nghĩ xem người dùng rốt cuộc muốn hoàn thành việc gì.</span></span></code></pre></div><p>AI có thể cho output hữu ích trông như thế này:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hướng JTBD khả dĩ:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Khi tôi lần đầu chuẩn bị nộp thực tập, tôi muốn nhanh chóng biết nên chuẩn bị những tài liệu nào trước,</span></span>
<span class="line"><span>để tôi không vì thông tin lộn xộn mà kéo dài không nộp.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Khi tôi thấy một vị trí thực tập, tôi muốn nhanh chóng đánh giá mình có đáng nộp hay không,</span></span>
<span class="line"><span>để tôi không lãng phí quá nhiều thời gian ở vị trí không phù hợp.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Khi tôi bắt đầu nộp hồ sơ, tôi muốn sửa CV hiện có thành phiên bản phù hợp với vị trí hơn,</span></span>
<span class="line"><span>để tôi có thể hoàn thành nộp nhanh hơn và tăng tỷ lệ được thông qua.</span></span></code></pre></div><p>Giá trị của loại output này là, nó sẽ tách ý tưởng rất rộng của bạn thành vài hướng gần với kịch bản thực tế hơn.</p><h3 id="_12-2-đe-ai-giup-ban-sap-xep-loi-goc-phong-van" tabindex="-1">12.2 Để AI giúp bạn sắp xếp lời gốc phỏng vấn <a class="header-anchor" href="#_12-2-đe-ai-giup-ban-sap-xep-loi-goc-phong-van" aria-label="Permalink to “12.2 Để AI giúp bạn sắp xếp lời gốc phỏng vấn”">​</a></h3><p>Nếu bạn đã làm vài lần phỏng vấn người dùng, có thể giao bản ghi phỏng vấn cho AI, để nó giúp bạn tinh lọc kịch bản, điểm kích hoạt, giải pháp thay thế và tiêu chuẩn thành công xuất hiện lặp đi lặp lại.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Dưới đây là lời gốc phỏng vấn của 5 người dùng.</span></span>
<span class="line"><span>Xin đừng cho giải pháp trước, mà sắp xếp theo framework JTBD:</span></span>
<span class="line"><span>1. Người dùng đang ở kịch bản nào</span></span>
<span class="line"><span>2. Sự kiện kích hoạt anh/chị hành động là gì</span></span>
<span class="line"><span>3. Tiến triển anh/chị thực sự muốn hoàn thành là gì</span></span>
<span class="line"><span>4. Giải pháp thay thế hiện tại là gì</span></span>
<span class="line"><span>5. Tiêu chuẩn thành công anh/chị quan tâm nhất là gì</span></span>
<span class="line"><span>6. Thông tin nào xuất hiện lặp lại ở nhiều người dùng</span></span>
<span class="line"><span>Cuối cùng sắp xếp thành 3 giả định JTBD đáng ưu tiên xác minh nhất.</span></span></code></pre></div><p>Một input rất đơn giản cũng có thể viết như sau:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi hỏi 3 người, họ đại khái nói như thế này:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Mỗi lần nộp thực tập tôi đều phải sửa lại CV, rất phiền.</span></span>
<span class="line"><span>2. Tôi thực sự sợ nhất là không biết mình viết đúng chưa.</span></span>
<span class="line"><span>3. Hiện tôi sẽ tìm anh chị khóa trên giúp xem, nhưng mỗi lần đều ngại phiền người ta mãi.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bạn giúp tôi sắp xếp, việc họ thực sự muốn hoàn thành là gì.</span></span></code></pre></div><p>AI có thể xuất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Kết quả sắp xếp:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Kịch bản chung: Trước khi chuẩn bị nộp thực tập, cần xử lý CV</span></span>
<span class="line"><span>- Khó khăn chung: Không biết sửa đến mức nào thì &quot;đủ tốt&quot;</span></span>
<span class="line"><span>- Giải pháp thay thế hiện tại: Tìm anh chị khóa trên giúp xem, tự mình sửa lặp đi lặp lại</span></span>
<span class="line"><span>- JTBD khả dĩ:</span></span>
<span class="line"><span>  Khi tôi chuẩn bị nộp thực tập, tôi muốn nhanh hơn đánh giá CV đã đạt mức có thể nộp chưa,</span></span>
<span class="line"><span>  để tôi không luôn kẹt ở &quot;sửa thêm chút nữa&quot; mà mãi không nộp được.</span></span></code></pre></div><p>Loại output này rất hữu dụng, vì nó giúp bạn từ lời gốc phân tán tinh lọc ra thứ giống &quot;nhu cầu&quot; hơn.</p><h3 id="_12-3-đe-ai-giup-ban-lam-mot-vong-nghien-cuu-mang-nhe-nhang" tabindex="-1">12.3 Để AI giúp bạn làm một vòng nghiên cứu mạng nhẹ nhàng <a class="header-anchor" href="#_12-3-đe-ai-giup-ban-lam-mot-vong-nghien-cuu-mang-nhe-nhang" aria-label="Permalink to “12.3 Để AI giúp bạn làm một vòng nghiên cứu mạng nhẹ nhàng”">​</a></h3><p>Trước khi bạn chưa bắt đầu phỏng vấn quy mô lớn, có thể trước để AI giúp bạn làm một số quét thông tin bên ngoài rất nhẹ, ví dụ:</p><ul><li>Trong diễn đàn hoặc cộng đồng công khai, mọi người phàn nàn về vấn đề này thế nào</li><li>Sản phẩm hiện có trên thị trường chủ yếu đang giải quyết tầng vấn đề nào</li><li>Giải pháp thay thế phổ biến nhất của người dùng là gì</li><li>Trong đánh giá phổ biến, điểm mọi người hài lòng và không hài lòng nhất là gì</li></ul><p>Loại nghiên cứu này không thể thay thế phỏng vấn người dùng thực tế, nhưng rất phù hợp làm khởi động cho giai đoạn Discover, giúp bạn xây bản đồ vấn đề trước.</p><p>Một input đơn giản:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Xin giúp tôi kiểm tra:</span></span>
<span class="line"><span>&quot;Sinh viên sửa CV, nộp thực tập thường gặp điểm đau nhất là gì?&quot;</span></span>
<span class="line"><span>Ưu tiên xem trong diễn đàn công khai, bài viết kinh nghiệm, cộng đồng tìm việc những gì mọi người tự nói.</span></span>
<span class="line"><span>Giúp tôi sắp xếp thành 5 vấn đề phổ biến nhất.</span></span></code></pre></div><p>AI có thể xuất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sắp xếp điểm đau phổ biến:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Không biết CV nên viết kinh nghiệm gì, kinh nghiệm quá ít</span></span>
<span class="line"><span>2. Không biết sửa cho phù hợp với vị trí khác nhau thế nào</span></span>
<span class="line"><span>3. Sửa nhiều phiên bản, nhưng luôn không chắc đã đủ tốt</span></span>
<span class="line"><span>4. Không tìm được người đáng tin cậy giúp xem</span></span>
<span class="line"><span>5. Quy trình nộp hồ sơ phức tạp, dễ trì hoãn</span></span></code></pre></div><p>Loại output này không thể làm kết luận cuối cùng, nhưng rất phù hợp giúp bạn trước quyết định ưu tiên phỏng vấn loại vấn đề nào.</p><h3 id="_12-4-đe-ai-đong-vai-ben-phan-đoi" tabindex="-1">12.4 Để AI đóng vai &quot;bên phản đối&quot; <a class="header-anchor" href="#_12-4-đe-ai-đong-vai-ben-phan-đoi" aria-label="Permalink to “12.4 Để AI đóng vai &quot;bên phản đối&quot;”">​</a></h3><p>Rất nhiều lúc, chúng ta quá có cảm tình với ý tưởng của mình. Bạn có thể chuyên để AI đóng vai người bắt lỗi, ép bạn nói rõ vấn đề hơn:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Xin đóng vai một cố vấn nghiên cứu sản phẩm rất nghiêm ngặt.</span></span>
<span class="line"><span>Dưới đây là giả định JTBD của tôi: [Giả định của bạn]</span></span>
<span class="line"><span>Xin phê bình nó từ các góc độ sau:</span></span>
<span class="line"><span>1. Kịch bản này có quá rộng không</span></span>
<span class="line"><span>2. Job này có phải viết thành chức năng thay vì tiến triển thực sự không</span></span>
<span class="line"><span>3. Giải pháp thay thế có quá yếu không</span></span>
<span class="line"><span>4. Tiêu chuẩn thành công có đủ rõ ràng không</span></span>
<span class="line"><span>5. Rủi ro cần được xác minh nhất của giả định này là gì</span></span></code></pre></div><p>Lợi ích của việc này là, bạn nhanh hơn phát hiện mình đang nhìn nhu cầu hay chỉ đang nhìn giải pháp mình thích.</p><h2 id="📚-bai-tap" tabindex="-1">📚 Bài tập <a class="header-anchor" href="#📚-bai-tap" aria-label="Permalink to “📚 Bài tập”">​</a></h2><p>Xin bạn dựa vào nội dung bài viết, hoàn thành bài tập sau:</p><ol><li>Chọn một ý tưởng sản phẩm bạn muốn làm gần đây, dùng một công thức JTBD viết rõ nó</li><li>Bổ sung 5 yếu tố cho ý tưởng này: Kịch bản, kích hoạt, tiến triển, giải pháp thay thế, tiêu chuẩn thành công</li><li>Tìm 3 người dùng tiềm năng, ít nhất hỏi được một lần &quot;lần gần nhất bạn gặp vấn đề này là khi nào&quot;</li><li>Giao lời gốc phỏng vấn cho AI, sắp xếp thành 3 giả định JTBD đáng ưu tiên xác minh nhất</li></ol><h2 id="đoc-them" tabindex="-1">Đọc thêm <a class="header-anchor" href="#đoc-them" aria-label="Permalink to “Đọc thêm”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{b as __pageData,d as default};
